      id: session.id,
      registered_user_id: session.registered_user_id,
      href: session.href,
      referrer: session.referrer,
      ip: session.ip,
      created_at: toISOStringSafe(session.created_at),
    })),
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

