        }),
      },
      skip,
      take: +limit,
      orderBy: { created_at: "desc" },
    }),
    MyGlobal.prisma.discussion_board_article_versions.count({
      where: {
        article_id: props.articleId,
        ...(search !== undefined && {
          OR: [
            { title: { contains: search } },
