    data: data.map((version) => ({
      id: version.id,
      title: version.title,
      created_at: toISOStringSafe(version.created_at),
    })),
    pagination: {
      current: +page,
      limit: +limit,
      records: total,
      pages: Math.ceil(total / +limit),
    },
  };
}

