import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardRegisteredUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRegisteredUser";
import { ModeratorPayload } from "../decorators/payload/ModeratorPayload";

export async function putDiscussionBoardModeratorRegisteredUsersUserId(props: {
  moderator: ModeratorPayload;
  userId: string & tags.Format<"uuid">;
  body: IDiscussionBoardRegisteredUser.IUpdate;
}): Promise<IDiscussionBoardRegisteredUser> {
  const existingUser =
    await MyGlobal.prisma.discussion_board_registered_users.findUnique({
      where: { id: props.userId },
    });
  if (!existingUser) {
    throw new HttpException("User not found", 404);
  }
  let updateBody: any;
  try {
    updateBody = JSON.parse(props.body as string);
  } catch (error) {
    throw new HttpException("Invalid update data", 400);
  }
  const updateData: Prisma.discussion_board_registered_usersUpdateInput = {
    ...(updateBody.email !== undefined && { email: updateBody.email }),
    updated_at: toISOStringSafe(new Date()),
  };
  const updatedUser =
    await MyGlobal.prisma.discussion_board_registered_users.update({
      where: { id: props.userId },
      data: updateData,
    });
  return {
    id: updatedUser.id satisfies string as string & tags.Format<"uuid">,
    email: updatedUser.email,
  } satisfies IDiscussionBoardRegisteredUser;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthModeratorLogin(props: {
  body: IDiscussionBoardModerator.ILogin;
}): Promise<IDiscussionBoardModerator.IAuthorized> {
  // Find moderator by username or email
  const moderator = await MyGlobal.prisma.discussion_board_moderators.findFirst(
    {
      where: {
        OR: [
          { username: props.body.usernameOrEmail },
          { email: props.body.usernameOrEmail },
        ],
      },
    },
  );
  if (!moderator) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    moderator.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Create new session
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const session =
    await MyGlobal.prisma.discussion_board_moderator_sessions.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        moderator_id: moderator.id,
        ip: "0.0.0.0",
        href: "/",
        referrer: "/",
        created_at: toISOStringSafe(new Date()),
        expired_at: accessExpires,
      },
    });

  // Generate JWT tokens
  const token = {
    access: jwt.sign(
      {
        type: "moderator",
        id: moderator.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "moderator",
        id: moderator.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  } satisfies IAuthorizationToken;

  // Return authorization information
  return {
    id: moderator.id,
    token,
  };
}

